import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {string} imageUrl
 * @property {Object} atlas
 * @property {number} atlas.sourceRectX
 * @property {number} atlas.sourceRectY
 * @property {number} atlas.sourceRectW
 * @property {number} atlas.sourceRectH
 * @property {Object} cinematicPrimitives
 * @property {Array} cinematicPrimitives[]
 * @property {Array} neighbors
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>THREE.Texture} textureLoader
 * @property {(url:string)=>Promise<any>} glbLoader
 * @property {Record<string,Function>} primitives
 * @property {(event:string)=>void} emit
 */

/**
 * Create a journal card node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // --- Geometry -------------------------------------------------------------
  const rectW = config.atlas?.sourceRectW ?? 512;
  const rectH = config.atlas?.sourceRectH ?? 320;
  const aspect = rectH / rectW;
  const geometry = new THREE.PlaneGeometry(1, aspect);

  // --- Texture ---------------------------------------------------------------
  const texture = ctx.textureLoader(config.imageUrl);
  texture.encoding = THREE.sRGBEncoding;
  texture.needsUpdate = true;

  // --- Material --------------------------------------------------------------
  const material = new MeshBasicNodeMaterial({ map: texture, transparent: true });

  // --- Mesh ------------------------------------------------------------------
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(
    config.position?.x ?? 0,
    config.position?.y ?? 0,
    config.position?.z ?? 0
  );
  mesh.rotation.set(
    config.rotation?.x ?? 0,
    config.rotation?.y ?? 0,
    config.rotation?.z ?? 0
  );
  mesh.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );

  // --- Interaction State -----------------------------------------------------
  const originalY = mesh.position.y;
  const hoverTween = {};

  // --- Handlers --------------------------------------------------------------
  const handlers = {};

  handlers.hoverEnter = () => {
    hoverTween.t = gsap.to(mesh.position, {
      y: originalY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  handlers.hoverLeave = () => {
    hoverTween.t = gsap.to(mesh.position, {
      y: originalY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  handlers.click = () => {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-journal.select');
    }
    // Press‑down visual feedback
    gsap.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
      yoyo: true,
      repeat: 1,
    });
  };

  // --- Cleanup ---------------------------------------------------------------
  const cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture && texture.dispose) texture.dispose();
    gsap.killTweensOf(mesh.position);
    gsap.killTweensOf(mesh.scale);
    mesh.userData.handlers = null;
  };

  // Attach data
  mesh.userData = {
    handlers,
    cleanup,
  };

  // Apply any cinematic primitives declared in config (none for this node)
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(mesh, prim.params);
      }
    });
  }

  return mesh;
}
